#!/usr/bin/env bash
# R14 ui lane art: the sleepy basket opening (shut + open) and the L10 mini boss portrait. ONE at a time via
# studio/bin/art.sh. Processed by proc_r14.py. usage: batch_r14.sh [name...]  (FORCE=1 to redo)
cd "$(dirname "$0")"
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green walls #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. One warm sunlight from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
K="Place every item on a flat solid pure magenta #ff00ff background with nothing else on it so it can be keyed out; no shadow on the background, items must not touch each other or the image edge."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n $(date +%T)"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }
run basket && g basket "Two items side by side with a wide magenta gap, same scale and same three-quarter view, the SAME basket in both: (1) a round chunky woven wicker cat basket in honey oak with a soft cream cushion and a small rust-red ribbon bow on the rim, an orange tabby cat curled up ASLEEP inside it, eyes shut, tail wrapped round its nose, a tiny cream blanket over its back; (2) the same basket tipped slightly forward, the SAME orange tabby cat now AWAKE and stretching up out of it with its front paws raised high, eyes open, happy open mouth yawn, the blanket sliding off, a few gold coins and a small wrapped gift spilling out over the rim. $K $S"
run boss_muffin && g boss_muffin "Single character, full body, sitting upright facing the viewer in a slight three-quarter view, a SMALL round chubby kitten mini boss, cute and lovable, never scary: a ginger and cream kitten as a little apprentice pastry chef, a short puffy white chef toque a bit too big for its head, a tiny pink bow on the side of the hat, a cream apron with a muffin-shaped pocket, holding up a small chocolate-chip muffin proudly in both paws, big shiny eyes, a cheeky determined pout with puffed cheeks, flour on one cheek. $K $S"
echo done $(date +%T)
